'use client'

import { useState } from 'react'
import { Database } from '@/types/database.types'
import { createBrowserClient } from '@supabase/ssr'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Card, CardContent } from '@/components/ui/card'
import { Checkbox } from '@/components/ui/checkbox'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { Plus, Trash2, Pencil, Settings2, Check, X } from 'lucide-react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog'
import { Label } from '@/components/ui/label'

type Ragazzo = Database['public']['Tables']['ragazzi']['Row']
type Pattuglia = Database['public']['Tables']['pattuglie']['Row']

export default function AnagraficaClient({ initialData, initialPattuglie }: { initialData: Ragazzo[], initialPattuglie: Pattuglia[] }) {
  const [ragazzi, setRagazzi] = useState<Ragazzo[]>(initialData)
  const [squadriglie, setSquadriglie] = useState<Pattuglia[]>(initialPattuglie)
  const [isOpen, setIsOpen] = useState(false)
  const [isSquadriglieOpen, setIsSquadriglieOpen] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [formData, setFormData] = useState({ nome: '', cognome: '', pattuglia: '' })

  // Stati per gestione Squadriglie
  const [newSquadriglia, setNewSquadriglia] = useState('')
  const [editingSqId, setEditingSqId] = useState<string | null>(null)
  const [editingSqNome, setEditingSqNome] = useState('')

  const supabase = createBrowserClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  )

  const updateRagazzo = async (id: string, field: keyof Ragazzo, value: any) => {
    setRagazzi((prev) =>
      prev.map((r) => (r.id === id ? { ...r, [field]: value } : r))
    )
    const updateData = { [field]: value } as Database['public']['Tables']['ragazzi']['Update']
    const { error } = await supabase.from('ragazzi').update(updateData).eq('id', id)
    if (error) console.error('Errore:', error)
    if (field === 'attivo' && value === false) {
      setRagazzi(prev => prev.filter(r => r.id !== id))
    }
  }

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault()
    if (editingId) {
      const { error } = await supabase.from('ragazzi').update({
        nome: formData.nome, cognome: formData.cognome, pattuglia: formData.pattuglia || null
      }).eq('id', editingId)
      if (!error) {
        setRagazzi(prev => prev.map(r => r.id === editingId ? { ...r, ...formData, pattuglia: formData.pattuglia || null } : r))
        setIsOpen(false)
        setEditingId(null)
        setFormData({ nome: '', cognome: '', pattuglia: '' })
      }
    } else {
      const { data, error } = await supabase.from('ragazzi').insert({
        nome: formData.nome, cognome: formData.cognome, pattuglia: formData.pattuglia || null, attivo: true
      }).select().single()
      if (!error && data) {
        setRagazzi([...ragazzi, data].sort((a, b) => (a.pattuglia || '').localeCompare(b.pattuglia || '')))
        setIsOpen(false)
        setFormData({ nome: '', cognome: '', pattuglia: '' })
      }
    }
  }

  // --- CRUD SQUADRIGLIE ---
  const handleAddSquadriglia = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!newSquadriglia.trim()) return
    const { data, error } = await supabase.from('pattuglie').insert({ nome: newSquadriglia.trim() }).select().single()
    if (!error && data) {
      setSquadriglie([...squadriglie, data])
      setNewSquadriglia('')
    }
  }

  const handleDeleteSquadriglia = async (id: string) => {
    if (!confirm('Vuoi eliminare questa squadriglia?')) return
    const { error } = await supabase.from('pattuglie').delete().eq('id', id)
    if (!error) {
      setSquadriglie(prev => prev.filter(s => s.id !== id))
    }
  }

  const saveEditSquadriglia = async (id: string) => {
    if (!editingSqNome.trim()) {
      setEditingSqId(null)
      return
    }
    const { error } = await supabase.from('pattuglie').update({ nome: editingSqNome.trim() }).eq('id', id)
    if (!error) {
      setSquadriglie(prev => prev.map(s => s.id === id ? { ...s, nome: editingSqNome.trim() } : s))
      setEditingSqId(null)
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex gap-2">
        <Dialog open={isOpen} onOpenChange={open => { setIsOpen(open); if(!open) setEditingId(null); }}>
          <DialogTrigger render={<Button variant="outline" className="hidden sm:flex"><Plus className="mr-2 h-4 w-4" /> Aggiungi Esploratore</Button>} />
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{editingId ? 'Modifica Esploratore' : 'Aggiungi Esploratore'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleAdd} className="space-y-4">
              <div className="space-y-2">
                <Label>Nome</Label>
                <Input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} />
              </div>
              <div className="space-y-2">
                <Label>Cognome</Label>
                <Input required value={formData.cognome} onChange={e => setFormData({...formData, cognome: e.target.value})} />
              </div>
              <div className="space-y-2">
                <Label>Squadriglia</Label>
                <Select value={formData.pattuglia} onValueChange={v => setFormData({...formData, pattuglia: v || ''})}>
                  <SelectTrigger><SelectValue placeholder="Seleziona..." /></SelectTrigger>
                  <SelectContent>
                    {squadriglie.map(p => p.nome ? (
                      <SelectItem key={p.id} value={p.nome}>{p.nome}</SelectItem>
                    ) : null)}
                  </SelectContent>
                </Select>
              </div>
              <Button type="submit" className="w-full">Salva</Button>
            </form>
          </DialogContent>
        </Dialog>

        <Dialog open={isSquadriglieOpen} onOpenChange={setIsSquadriglieOpen}>
          <DialogTrigger render={<Button variant="outline" className="hidden sm:flex"><Settings2 className="mr-2 h-4 w-4" /> Gestione Squadriglie</Button>} />
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Gestione Squadriglie</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <form onSubmit={handleAddSquadriglia} className="flex gap-2">
                <Input placeholder="Nuova squadriglia..." value={newSquadriglia} onChange={e => setNewSquadriglia(e.target.value)} required />
                <Button type="submit"><Plus className="h-4 w-4" /></Button>
              </form>
              <div className="space-y-2 max-h-60 overflow-y-auto">
                {squadriglie.map(sq => (
                  <div key={sq.id} className="flex justify-between items-center p-2 border rounded-md">
                    {editingSqId === sq.id ? (
                      <div className="flex gap-2 w-full">
                        <Input className="h-8" value={editingSqNome} onChange={e => setEditingSqNome(e.target.value)} autoFocus />
                        <Button size="icon" variant="ghost" className="h-8 w-8 text-green-600" onClick={() => saveEditSquadriglia(sq.id)}><Check className="h-4 w-4" /></Button>
                        <Button size="icon" variant="ghost" className="h-8 w-8 text-red-500" onClick={() => setEditingSqId(null)}><X className="h-4 w-4" /></Button>
                      </div>
                    ) : (
                      <>
                        <span className="text-sm">{sq.nome}</span>
                        <div className="flex gap-1">
                          <Button size="icon" variant="ghost" className="h-8 w-8 text-blue-600" onClick={() => { setEditingSqId(sq.id); setEditingSqNome(sq.nome || ''); }}>
                            <Pencil className="h-4 w-4" />
                          </Button>
                          <Button size="icon" variant="ghost" className="h-8 w-8 text-red-500" onClick={() => handleDeleteSquadriglia(sq.id)}>
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {/* Vista Desktop (Griglia) */}
      <div className="hidden md:block rounded-md border bg-card">
        <Table className="text-sm">
          <TableHeader className="bg-muted">
            <TableRow className="h-8">
              <TableHead className="py-1 px-2 border-r">Nome e Cognome</TableHead>
              <TableHead className="py-1 px-2 border-r">Squadriglia</TableHead>
              <TableHead className="py-1 px-2 text-center border-r">Privacy</TableHead>
              <TableHead className="py-1 px-2 text-center w-12"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {ragazzi.map((ragazzo) => (
              <TableRow key={ragazzo.id} className="h-10 border-b">
                <TableCell className="font-medium p-1 border-r">
                  <div className="flex items-center space-x-1">
                    <span>{ragazzo.nome} {ragazzo.cognome}</span>
                    <Button variant="ghost" size="icon" className="h-6 w-6 text-blue-600" onClick={() => {
                              setEditingId(ragazzo.id)
                              setFormData({ nome: ragazzo.nome, cognome: ragazzo.cognome, pattuglia: ragazzo.pattuglia || '' })
                              setIsOpen(true)
                            }}>
                      <Pencil className="h-3 w-3" />
                    </Button>
                  </div>
                </TableCell>
                <TableCell className="p-1 border-r">
                  <Select
                    defaultValue={ragazzo.pattuglia || undefined}
                    onValueChange={(val) => updateRagazzo(ragazzo.id, 'pattuglia', val)}
                  >
                    <SelectTrigger className="h-8 w-full border-0 shadow-none focus:ring-1">
                      <SelectValue placeholder="Seleziona..." />
                    </SelectTrigger>
                    <SelectContent>
                      {squadriglie.map(p => p.nome ? (
                        <SelectItem key={p.id} value={p.nome}>{p.nome}</SelectItem>
                      ) : null)}
                    </SelectContent>
                  </Select>
                </TableCell>
                <TableCell className="p-1 text-center">
                  <div className="flex justify-center w-full">
                    <Checkbox
                      checked={ragazzo.foglio_privacy_firmato || false}
                      onCheckedChange={(checked) => 
                        updateRagazzo(ragazzo.id, 'foglio_privacy_firmato', checked === true)
                      }
                    />
                  </div>
                </TableCell>
                <TableCell className="p-1 text-center w-12">
                  <Button variant="ghost" size="icon" className="h-8 w-8 text-red-500 hover:text-red-700 hover:bg-red-50" onClick={() => { if(confirm('Vuoi archiviare questo ragazzo?')) updateRagazzo(ragazzo.id, 'attivo', false) }}>
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </TableCell>
              </TableRow>
            ))}
            {ragazzi.length === 0 && (
              <TableRow>
                <TableCell colSpan={4} className="text-center py-4">Nessun ragazzo trovato.</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      {/* Vista Mobile (Cards) */}
      <div className="md:hidden space-y-4">
        {ragazzi.map((ragazzo) => (
          <Card key={ragazzo.id}>
            <CardContent className="p-4 flex justify-between items-center">
              <div>
                <p className="font-bold text-lg">{ragazzo.nome} {ragazzo.cognome}</p>
                <p className="text-sm text-muted-foreground">{ragazzo.pattuglia || 'Nessuna squadriglia'}</p>
              </div>
              <div className="flex flex-col items-center gap-1">
                <span className="text-[10px] text-muted-foreground">Privacy</span>
                <Checkbox
                  className="h-6 w-6"
                  checked={ragazzo.foglio_privacy_firmato || false}
                  onCheckedChange={(checked) => 
                    updateRagazzo(ragazzo.id, 'foglio_privacy_firmato', checked === true)
                  }
                />
                <Button variant="ghost" size="icon" className="h-6 w-6 mt-2 text-red-500" onClick={() => { if(confirm('Vuoi archiviare questo ragazzo?')) updateRagazzo(ragazzo.id, 'attivo', false) }}>
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}
